/// \file
/// This file declares the targeting of the RegisterBankInfo class for VCSIR.
/// \todo This should be generated by TableGen.
//===----------------------------------------------------------------------===//

#ifndef LLVM_LIB_TARGET_VCSIR_VCSIRREGISTERBANKINFO_H
#define LLVM_LIB_TARGET_VCSIR_VCSIRREGISTERBANKINFO_H

#include "llvm/CodeGen/RegisterBankInfo.h"

#define GET_REGBANK_DECLARATIONS
#include "VCSIRGenRegisterBank.inc"

namespace llvm {

class TargetRegisterInfo;

class VCSIRGenRegisterBankInfo : public RegisterBankInfo {
protected:
#define GET_TARGET_REGBANK_CLASS
#include "VCSIRGenRegisterBank.inc"
};

/// This class provides the information for the target register banks.
class VCSIRRegisterBankInfo final : public VCSIRGenRegisterBankInfo {
public:
  VCSIRRegisterBankInfo(unsigned HwMode);

  const InstructionMapping &
  getInstrMapping(const MachineInstr &MI) const override;

private:
  /// \returns true if \p MI only uses and defines FPRs.
  bool hasFPConstraints(const MachineInstr &MI, const MachineRegisterInfo &MRI,
                        const TargetRegisterInfo &TRI) const;

  /// \returns true if \p MI only uses FPRs.
  bool onlyUsesFP(const MachineInstr &MI, const MachineRegisterInfo &MRI,
                  const TargetRegisterInfo &TRI) const;

  /// \returns true if any use of \p Def only user FPRs.
  bool anyUseOnlyUseFP(Register Def, const MachineRegisterInfo &MRI,
                       const TargetRegisterInfo &TRI) const;

  /// \returns true if \p MI only defines FPRs.
  bool onlyDefinesFP(const MachineInstr &MI, const MachineRegisterInfo &MRI,
                     const TargetRegisterInfo &TRI) const;
};
} // end namespace llvm
#endif
